    /**
     * `Y.applyUpdate(doc, update, origin)`.
     */
    func applyUpdate(update: Data, origin: String) throws 
    
    /**
     * Applies several updates in one transaction (faster for loading from storage).
     */
    func applyUpdates(updates: [Data], origin: String) throws 
    
    func arrayGet(root: String) throws  -> [YValue]
    
    func canRedo()  -> Bool
    
    func canUndo()  -> Bool
    
    func clearUndo() 
    
    func clientId()  -> UInt64
    
    /**
