/**
 * One write operation. Paths of XML ops are child indices from the XML root; paths of map
 * ops are keys of nested shared maps from the root map.
 */

public enum YOp: Equatable, Hashable {
    
    case mapSet(root: String, path: [String], key: String, value: YValue
    )
    case mapDelete(root: String, path: [String], key: String
    )
    case arrayInsert(root: String, index: UInt32, items: [YValue]
    )
    case arrayDelete(root: String, index: UInt32, len: UInt32
    )
    case xmlInsert(root: String, parent: [UInt32], index: UInt32, nodes: [XmlNode]
    )
    case xmlDelete(root: String, parent: [UInt32], index: UInt32, len: UInt32
    )
    case xmlSetAttribute(root: String, path: [UInt32], key: String, value: YValue
    )
    case xmlRemoveAttribute(root: String, path: [UInt32], key: String
    )
    case textInsert(root: String, path: [UInt32], index: UInt32, chunks: [TextChunk]
    )
    case textDelete(root: String, path: [UInt32], index: UInt32, len: UInt32
    )
    /**
     * Applies formatting attributes; a `Null` value removes that attribute.
     */
    case textFormat(root: String, path: [UInt32], index: UInt32, len: UInt32, attributes: [String: YValue]
    )
    /**
     * Root `Y.Text` edits (not used by the note schema, kept for completeness).
     */
    case rootTextInsert(root: String, index: UInt32, text: String
    )
    case rootTextDelete(root: String, index: UInt32, len: UInt32
    )





}

